{"command":"cat <<'PY' > /tmp/server_probe2.py
import socket, subprocess, time, os, select, re, hashlib, hmac, uuid, json
def clean(b): return re.sub(rb'\x1b\[[0-9;]*m',b'',b)
def drain(srv):
    out=b""
    while True:
        r,_,_=select.select([srv.stdout],[],[],0.2)
        if not r: break
        d=os.read(srv.stdout.fileno(),8192)
        if not d: break
        out+=d
    if out: print(" SRV:",clean(out).decode(errors='ignore'),end='',flush=True)
    return out

def handshake_and_probe(label, first_msgs, server_secret="mysecret"):
    print(f"\n=== {label} ===")
    srv=subprocess.Popen(["./executable","server","--secret",server_secret],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    time.sleep(0.4); drain(srv)
    s=socket.create_connection(("127.0.0.1",7835),timeout=5); s.settimeout(1)
    # get challenge
    challenge=None
    try:
        data=s.recv(4096); print(" initial recv:",data)
        msgs=data.split(b'\x00')
        for m in msgs:
            if m.startswith(b'{"Challenge"'):
                challenge=json.loads(m)["Challenge"]
    except Exception as e: print(" initial err",e)
    print(" challenge uuid:",challenge)
    def compute(secret):
        if challenge is None: return "00"
        key=hashlib.sha256(secret.encode()).digest()
        return hmac.new(key, uuid.UUID(challenge).bytes, hashlib.sha256).hexdigest()
    # first_msgs is list of templates: can use {AUTH} placeholder for correct, {AUTH_WRONG}
    for tmpl in first_msgs:
        if tmpl=="AUTH_CORRECT":
            m=json.dumps({"Authenticate":compute(server_secret)}).encode()+b'\x00'
        elif tmpl=="AUTH_WRONG_SECRET":
            m=json.dumps({"Authenticate":compute("wrong")}).encode()+b'\x00'
        elif tmpl=="AUTH_GARBAGE":
            m=b'{"Authenticate":"zzzz"}\x00'
        elif isinstance(tmpl,bytes):
            m=tmpl
        else:
            m=tmpl.encode()
        print(" ->",m)
        try: s.sendall(m)
        except Exception as e: print(" send err",e); break
        try: print(" <-",s.recv(4096))
        except Exception as e: print(" <- err",e)
        drain(srv)
    s.close(); time.sleep(0.3); drain(srv)
    srv.terminate()
    out,err=srv.communicate(timeout=2)
    if out or err: print(" final:",clean(out),err)
    time.sleep(0.2)

handshake_and_probe("wrong auth hex value dummy",["AUTH_WRONG_SECRET"])
handshake_and_probe("garbage auth zzzz",["AUTH_GARBAGE"])
handshake_and_probe("auth empty string",[b'{"Authenticate":""}\x00'])
handshake_and_probe("hello instead of auth",[b'{"Hello":18081}\x00'])
handshake_and_probe("accept instead of auth",[b'{"Accept":"ea88ba2c-d83f-46bf-8f30-71f04ddd2835"}\x00'])
handshake_and_probe("invalid json instead of auth",[b'garbage\x00'])
handshake_and_probe("correct auth then hello",["AUTH_CORRECT",b'{"Hello":18081}\x00'])
handshake_and_probe("correct auth then authenticate again",["AUTH_CORRECT","AUTH_CORRECT"])
handshake_and_probe("correct auth then invalid json",["AUTH_CORRECT",b'garbage\x00'])
handshake_and_probe("correct auth then close (no 2nd msg)",["AUTH_CORRECT"])
handshake_and_probe("correct auth then accept unknown",["AUTH_CORRECT",b'{"Accept":"ea88ba2c-d83f-46bf-8f30-71f04ddd2835"}\x00'])
handshake_and_probe("no response to challenge, just close",[])
# auth uppercase hex ?
# challenge reply computed with uppercase ?
