def clean(b): return re.sub(rb'\x1b\[[0-9;]*m',b'',b)

def run(label, client_args, server_actions):
    # server_actions: list of (delay, bytes_or_None_or_close)
    print(f"\n=== {label} args={client_args} actions={server_actions} ===",flush=True)
    srv_sock=socket.socket(); srv_sock.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv_sock.bind(('127.0.0.1',7835)); srv_sock.listen(5); srv_sock.settimeout(5)
    start=time.time()
    client=subprocess.Popen(["./executable","local","18080","--to","127.0.0.1","--port","18081"]+client_args,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    logs_out=[]; logs_err=[]
    def reader(f,store,name):
        for l in iter(f.readline,b''):
            print(f"[{time.time()-start:.2f}] {name} {clean(l)!r}",flush=True); store.append(l)
    threading.Thread(target=reader,args=(client.stdout,logs_out,"OUT"),daemon=True).start()
    threading.Thread(target=reader,args=(client.stderr,logs_err,"ERR"),daemon=True).start()
    try:
        conn,addr=srv_sock.accept()
        print(f"[{time.time()-start:.2f}] accepted {addr}",flush=True)
    except Exception as e:
        print("accept err",e); client.terminate(); srv_sock.close(); return
    conn.settimeout(0.4)
    # first try peek client first message if any within 0.4
    try:
        data=conn.recv(4096); print(f"[{time.time()-start:.2f}] initial from client: {data!r}")
    except Exception as e:
        print(f"[{time.time()-start:.2f}] no initial from client ({e})")
    for action in server_actions:
        if isinstance(action,(int,float)):
            time.sleep(action); continue
        if action==b"CLOSE":
            print("closing conn"); conn.close(); break
        print(f"[{time.time()-start:.2f}] -> send {action!r}")
        try: conn.sendall(action)
        except Exception as e: print("send err",e)
        # read response for up to 0.8
        conn.settimeout(0.8)
        try:
            while True:
                data=conn.recv(4096); print(f"[{time.time()-start:.2f}] <- {data!r}")
                if not data: break
                break
        except Exception as e: print(f"[{time.time()-start:.2f}] <- timeout/err {e}")
    # wait for client exit up to 4 sec
    for i in range(40):
        if client.poll() is not None: break
        time.sleep(0.1)
    print(f"[{time.time()-start:.2f}] client poll={client.poll()}")
    if client.poll() is None:
        client.terminate()
    try: client.communicate(timeout=2)
    except: client.kill()
    try: conn.close()
    except: pass
    srv_sock.close()
    time.sleep(0.3)

