import socket, subprocess, time, threading, re
def clean(b): return re.sub(rb'\x1b\[[0-9;]*m',b'',b)
def run(label, client_args, actions):
    # actions list of tuple(delay_before, data_or_None)
    print(f"\n=== {label} ===",flush=True)
    listener=socket.socket(); listener.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); listener.bind(('127.0.0.1',7835)); listener.listen(5)
    start=time.time()
    client=subprocess.Popen(["./executable","local","18080","--to","127.0.0.1","--port","18081"]+client_args,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    def reader(f,name):
        for l in iter(f.readline,b''):
            print(f"[{time.time()-start:.2f}] {name} {clean(l)!r}",flush=True)
    threading.Thread(target=reader,args=(client.stdout,"OUT"),daemon=True).start()
    threading.Thread(target=reader,args=(client.stderr,"ERR"),daemon=True).start()
    conn,_=listener.accept(); conn.settimeout(5)
    print(f"[{time.time()-start:.2f}] accepted",flush=True)
    # drain reader thread for client messages
    def conn_reader():
        while True:
            try:
                d=conn.recv(4096)
            except Exception as e:
                print(f"[{time.time()-start:.2f}] conn reader err {e}"); break
            print(f"[{time.time()-start:.2f}] <- client {d!r}",flush=True)
            if not d: break
    threading.Thread(target=conn_reader,daemon=True).start()
    for delay,data in actions:
        if delay: 
            print(f"[{time.time()-start:.2f}] sleeping {delay}",flush=True); time.sleep(delay)
