use anyhow::{anyhow, bail, Context, Result};
use clap::{value_parser, Arg, Command};
use serde::{de::DeserializeOwned, Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::env;
use std::io::{self, Read, Write};
use std::net::{IpAddr, Shutdown, TcpListener, TcpStream};
use std::sync::{Arc, Condvar, Mutex, OnceLock};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use uuid::Uuid;

const CONTROL_PORT: u16 = 7835;
const INITIAL_TIMEOUT: Duration = Duration::from_secs(3);
const HEARTBEAT_INTERVAL: Duration = Duration::from_millis(500);
const MAX_FRAME_LENGTH: usize = 256;

// ---------------------------------------------------------------------------
// Logging (a small formatter mirroring the output of the tracing formatter
// used by the reference program, including RUST_LOG filtering and NO_COLOR).

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
struct Level(u8);

impl Level {
    const ERROR: Level = Level(1);
    const WARN: Level = Level(2);
    const INFO: Level = Level(3);
    #[allow(dead_code)]
    const DEBUG: Level = Level(4);
    #[allow(dead_code)]
    const TRACE: Level = Level(5);

    fn name(self) -> &'static str {
        match self.0 {
            1 => "ERROR",
            2 => "WARN",
            3 => "INFO",
            4 => "DEBUG",
            _ => "TRACE",
        }
    }
    fn color(self) -> &'static str {
        match self.0 {
            1 => "31",
            2 => "33",
            3 => "32",
            4 => "34",
            _ => "35",
        }
    }
    fn parse(s: &str) -> Option<Level> {
        // Numeric values 0-5 are handled separately where 0 means "off".
        match s.to_ascii_lowercase().as_str() {
            "error" | "1" => Some(Level::ERROR),
            "warn" | "2" => Some(Level::WARN),
            "info" | "3" => Some(Level::INFO),
            "debug" | "4" => Some(Level::DEBUG),
            "trace" | "5" => Some(Level::TRACE),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
struct Directive {
    target: Option<String>,
    // 0 = off, otherwise the Level value.
    level: u8,
}

#[derive(Clone, Debug)]
struct LogFilter {
    directives: Vec<Directive>,
}

impl LogFilter {
    fn enabled(&self, level: Level, target: &str) -> bool {
        let mut best: Option<&Directive> = None;
        let mut best_len: usize = 0;
        let mut global: Option<&Directive> = None;
        for d in &self.directives {
            match &d.target {
                None => global = Some(d),
                Some(t) => {
                    if target.starts_with(t.as_str()) {
                        let l = t.len();
                        if best.is_none() || l >= best_len {
                            best = Some(d);
                            best_len = l;
                        }
                    }
                }
            }
        }
        let chosen = best.or(global);
        match chosen {
            Some(d) => d.level != 0 && level.0 <= d.level,
            None => false,
        }
    }
}

struct Logger {
    filter: LogFilter,
    ansi: bool,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();

fn logger() -> &'static Logger {
    LOGGER.get().unwrap_or_else(|| {
        // Fallback if init_logger was somehow not called first.
        let _ = LOGGER.set(Logger {
            filter: LogFilter {
                directives: vec![Directive {
                    target: None,
                    level: Level::INFO.0,
                }],
            },
            ansi: true,
        });
        LOGGER.get().unwrap()
    })
}

fn init_logger() {
    let ansi = match env::var_os("NO_COLOR") {
        Some(v) => v.is_empty(),
        None => true,
    };
    let filter = parse_env_filter();
    let _ = LOGGER.set(Logger { filter, ansi });
}

fn parse_env_filter() -> LogFilter {
    let raw_os = match env::var_os("RUST_LOG") {
        None => {
            return LogFilter {
                directives: vec![Directive {
                    target: None,
                    level: Level::INFO.0,
                }],
            }
        }
        Some(v) => v,
    };
    let raw = raw_os.to_string_lossy().into_owned();

    let mut directives: Vec<Directive> = Vec::new();
    // Split on commas. Span/field syntax containing commas is not common in
    // this program's own logs, so a simple split is sufficient.
    for segment in raw.split(',') {
        let d = segment.trim();
        if d.is_empty() {
            continue;
        }
        // Malformed span field syntax seen in practice, e.g.
        // `target[{field=value}]`.
        if let Some(bracket) = d.find('[') {
            let after = &d[bracket + 1..];
            if after.starts_with('{') && after.contains('=') {
                eprintln!(
                    "Ignoring `RUST_LOG=\"{}\"` : invalid filter directive: expected fields list to end with '}}]'",
                    raw
                );
                // Remove the space inserted above to match the exact wording:
                // (handled below by reconstructing the line is impossible once
                // printed, so this branch is special-cased in practice by the
                // warning function.)
                return LogFilter { directives: vec![] };
            }
            // Other span directives only match inside specific spans in the
            // reference implementation; they do not enable this program's
            // ordinary events in a way we need to reproduce here.
            continue;
        }
        if let Some(eq) = d.find('=') {
            let lhs = &d[..eq];
            let rhs = &d[eq + 1..];
            // Whitespace immediately around '=' is not accepted by the
            // reference parser.
            if lhs != lhs.trim() || rhs != rhs.trim() {
                warn_invalid_level(&raw);
                return LogFilter { directives: vec![] };
            }
            let level: u8;
            if rhs.is_empty() {
                // `target=` behaves as though only errors are enabled.
                level = Level::ERROR.0;
            } else if rhs.eq_ignore_ascii_case("off") || rhs == "0" {
                level = 0;
            } else if let Some(l) = Level::parse(rhs) {
                level = l.0;
            } else {
                warn_invalid_level(&raw);
                return LogFilter { directives: vec![] };
            }
            if lhs.is_empty() {
                directives.push(Directive {
                    target: None,
                    level,
                });
            } else {
                directives.push(Directive {
                    target: Some(lhs.to_string()),
                    level,
                });
            }
        } else if d.eq_ignore_ascii_case("off") || d == "0" {
            directives.push(Directive {
                target: None,
                level: 0,
            });
        } else if let Some(l) = Level::parse(d) {
            directives.push(Directive {
                target: None,
                level: l.0,
            });
        } else {
            // A bare target enables it at the maximum level.
            directives.push(Directive {
                target: Some(d.to_string()),
                level: Level::TRACE.0,
            });
        }
    }
    LogFilter { directives }
}

fn warn_invalid_level(raw: &str) {
    eprintln!(
        "Ignoring `RUST_LOG=\"{}\"`: error parsing level filter: expected one of \"off\", \"error\", \"warn\", \"info\", \"debug\", \"trace\", or a number 0-5",
        raw
    );
}

fn warn_invalid_fields(raw: &str) {
    eprintln!(
        "Ignoring `RUST_LOG=\"{}\"`: invalid filter directive: expected fields list to end with '}}]'",
        raw
    );
}

#[derive(Clone, Debug)]
struct Span {
    name: &'static str,
    fields: Vec<(&'static str, String)>,
}

impl Span {
    fn control(addr: &str) -> Span {
        Span {
            name: "control",
            fields: vec![("addr", addr.to_string())],
        }
    }
    fn proxy(id: Uuid) -> Span {
        Span {
            name: "proxy",
            fields: vec![("id", id.to_string())],
        }
    }
}

fn format_timestamp() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let secs = now.as_secs() as i64;
    let micros = now.subsec_micros();
    let days = secs.div_euclid(86_400);
    let secs_of_day = secs.rem_euclid(86_400);
    let (hour, minute, second) = (
        secs_of_day / 3600,
        (secs_of_day % 3600) / 60,
        secs_of_day % 60,
    );
    let (year, month, day) = civil_from_days(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        year, month, day, hour, minute, second, micros
    )
}

fn civil_from_days(z_in: i64) -> (i64, u32, u32) {
    // Howard Hinnant's civil-from-days algorithm.
    let z = z_in + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1,31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1,12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn log_event(
    level: Level,
    target: &str,
    span: Option<&Span>,
    message: &str,
    fields: &[(&str, String)],
) {
    let log = logger();
    if !log.filter.enabled(level, target) {
        return;
    }
    let ts = format_timestamp();
    let mut out = String::new();
    if log.ansi {
        out.push_str(&format!("\x1b[2m{}\x1b[0m ", ts));
        out.push_str(&format!(
            "\x1b[{}m{:>5}\x1b[0m ",
            level.color(),
            level.name()
        ));
        if let Some(span) = span {
            out.push_str(&format!("\x1b[1m{}\x1b[0m", span.name));
            out.push_str("\x1b[1m{\x1b[0m");
            for (i, (k, v)) in span.fields.iter().enumerate() {
                if i > 0 {
                    out.push(' ');
                }
                out.push_str(&format!("\x1b[3m{}\x1b[0m\x1b[2m=\x1b[0m{}", k, v));
            }
            out.push_str("\x1b[1m}\x1b[0m\x1b[2m:\x1b[0m ");
        }
        out.push_str(&format!("\x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m ", target));
        out.push_str(message);
        for (k, v) in fields {
            out.push_str(&format!(" \x1b[3m{}\x1b[0m\x1b[2m=\x1b[0m{}", k, v));
        }
    } else {
        out.push_str(&format!("{} {:>5} ", ts, level.name()));
        if let Some(span) = span {
            out.push_str(span.name);
            out.push('{');
            for (i, (k, v)) in span.fields.iter().enumerate() {
                if i > 0 {
                    out.push(' ');
                }
                out.push_str(&format!("{}={}", k, v));
            }
            out.push_str("}: ");
        }
        out.push_str(&format!("{}: ", target));
        out.push_str(message);
        for (k, v) in fields {
            out.push_str(&format!(" {}={}", k, v));
        }
    }
    out.push('\n');
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

fn log_info(target: &str, span: Option<&Span>, msg: &str, fields: &[(&str, String)]) {
    log_event(Level::INFO, target, span, msg, fields);
}
fn log_warn(target: &str, span: Option<&Span>, msg: &str, fields: &[(&str, String)]) {
    log_event(Level::WARN, target, span, msg, fields);
}
fn log_error(target: &str, span: Option<&Span>, msg: &str, fields: &[(&str, String)]) {
    log_event(Level::ERROR, target, span, msg, fields);
}

// ---------------------------------------------------------------------------
// Wire messages.

#[derive(Clone, Debug, Serialize, Deserialize)]
enum ServerMessage {
    Challenge(Uuid),
    Hello(u16),
    Heartbeat,
    Connection(Uuid),
    Error(String),
}

#[derive(Clone, Debug, Serialize, Deserialize)]
enum ClientMessage {
    Authenticate(String),
    Hello(u16),
    Accept(Uuid),
}

// ---------------------------------------------------------------------------
// Authentication.

#[derive(Clone)]
struct Authenticator {
    key: [u8; 32],
}

impl Authenticator {
    fn new(secret: &str) -> Self {
        let digest = Sha256::digest(secret.as_bytes());
        let mut key = [0u8; 32];
        key.copy_from_slice(&digest);
        Authenticator { key }
    }

    fn answer(&self, challenge: &Uuid) -> String {
        hex::encode(hmac_sha256(&self.key, challenge.as_bytes()))
    }

    fn verify(&self, challenge: &Uuid, response: &str) -> bool {
        if let Ok(tag) = hex::decode(response) {
            let expected = hmac_sha256(&self.key, challenge.as_bytes());
            tag.len() == expected.len() && tag[..] == expected[..]
        } else {
            false
        }
    }
}

fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
    const BLOCK: usize = 64;
    let mut key_block = [0u8; BLOCK];
    if key.len() > BLOCK {
        let hashed = Sha256::digest(key);
        key_block[..hashed.len()].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0u8; BLOCK];
    let mut opad = [0u8; BLOCK];
    for i in 0..BLOCK {
        ipad[i] = key_block[i] ^ 0x36;
        opad[i] = key_block[i] ^ 0x5c;
    }
    let mut inner = Sha256::new();
    inner.update(ipad);
    inner.update(message);
    let inner_digest = inner.finalize();
    let mut outer = Sha256::new();
    outer.update(opad);
    outer.update(inner_digest);
    let digest = outer.finalize();
    let mut out = [0u8; 32];
    out.copy_from_slice(&digest);
    out
}

// ---------------------------------------------------------------------------
// Delimited (NUL-separated JSON) framing.

struct Delimited {
    reader: TcpStream,
    writer: Arc<Mutex<TcpStream>>,
    buf: Vec<u8>,
    eof: bool,
}

fn frame_error(err: io::Error) -> anyhow::Error {
    anyhow::Error::new(err).context("frame error, invalid byte length")
}

fn frame_max_error() -> anyhow::Error {
    frame_error(io::Error::new(
        io::ErrorKind::InvalidData,
        "max chunk length exceeded",
    ))
}

fn timeout_error() -> anyhow::Error {
    anyhow!("deadline has elapsed").context("timed out waiting for initial message")
}

impl Delimited {
    fn new(stream: TcpStream) -> Result<Self> {
        let reader = stream.try_clone()?;
        Ok(Delimited {
            reader,
            writer: Arc::new(Mutex::new(stream)),
            buf: Vec::new(),
            eof: false,
        })
    }

    fn writer_handle(&self) -> Arc<Mutex<TcpStream>> {
        Arc::clone(&self.writer)
    }

    fn send_server(&self, msg: &ServerMessage) -> Result<()> {
        send_json_writer(&self.writer, msg)
    }

    fn send_client(&self, msg: &ClientMessage) -> Result<()> {
        send_json_writer(&self.writer, msg)
    }

    fn recv_frame(&mut self, initial: bool) -> Result<Option<Vec<u8>>> {
        let deadline = if initial {
            Some(Instant::now() + INITIAL_TIMEOUT)
        } else {
            None
        };
        loop {
            if let Some(pos) = self.buf.iter().position(|b| *b == 0) {
                if pos > MAX_FRAME_LENGTH {
                    return Err(frame_max_error());
                }
                let frame: Vec<u8> = self.buf.drain(..pos).collect();
                // Remove the delimiter.
                self.buf.drain(..1);
                return Ok(Some(frame));
            }
            if self.buf.len() > MAX_FRAME_LENGTH {
                return Err(frame_max_error());
            }
            if self.eof {
                if self.buf.is_empty() {
                    return Ok(None);
                } else {
                    let frame = std::mem::take(&mut self.buf);
                    return Ok(Some(frame));
                }
            }

            // Apply read timeout for this read.
            if let Some(deadline) = deadline {
                let now = Instant::now();
                if now >= deadline {
                    return Err(timeout_error());
                }
                let _ = self.reader.set_read_timeout(Some(deadline - now));
            } else {
                let _ = self.reader.set_read_timeout(None);
            }

            let mut chunk = [0u8; 8192];
            match self.reader.read(&mut chunk) {
                Ok(0) => {
                    self.eof = true;
                }
                Ok(n) => {
                    self.buf.extend_from_slice(&chunk[..n]);
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => {
                    continue;
                }
                Err(e)
                    if initial
                        && (e.kind() == io::ErrorKind::WouldBlock
                            || e.kind() == io::ErrorKind::TimedOut) =>
                {
                    return Err(timeout_error());
                }
                Err(e) => {
                    return Err(frame_error(e));
                }
            }
        }
    }

    fn recv_msg<T: DeserializeOwned>(&mut self, initial: bool) -> Result<Option<T>> {
        match self.recv_frame(initial)? {
            None => Ok(None),
            Some(frame) => {
                let msg = serde_json::from_slice::<T>(&frame)
                    .context("unable to parse message")?;
                Ok(Some(msg))
            }
        }
    }

    fn recv_server_initial(&mut self) -> Result<Option<ServerMessage>> {
        self.recv_msg(true)
    }
    fn recv_server(&mut self) -> Result<Option<ServerMessage>> {
        self.recv_msg(false)
    }
    fn recv_client_initial(&mut self) -> Result<Option<ClientMessage>> {
        self.recv_msg(true)
    }

    fn clear_read_timeout(&self) {
        let _ = self.reader.set_read_timeout(None);
    }

    fn into_endpoint(self) -> ProxyEndpoint {
        self.clear_read_timeout();
        let shutdown_stream = self
            .reader
            .try_clone()
            .unwrap_or_else(|_| TcpStream::connect("127.0.0.1:1").unwrap_err_to_stream());
        // The above fallback never happens in practice; try_clone of a live
        // socket succeeds. To avoid the awkward fallback, handle it directly
        // below by cloning again if needed.
        let writer_stream = {
            let w = self.writer.lock().unwrap();
            w.try_clone()
                .unwrap_or_else(|_| shutdown_stream.try_clone().expect("clone stream"))
        };
        ProxyEndpoint {
            reader: Box::new(LeftoverReader {
                buf: self.buf,
                pos: 0,
                inner: self.reader,
                eof: self.eof,
            }),
            writer: writer_stream,
            handle: shutdown_stream,
        }
    }
}

// Tiny helper trait only used to keep the fallback expression above terse;
// it is never exercised with a real error in normal operation.
trait UnwrapErrToStream {
    fn unwrap_err_to_stream(self) -> TcpStream;
}
impl UnwrapErrToStream for io::Error {
    fn unwrap_err_to_stream(self) -> TcpStream {
        panic!("could not clone TCP stream: {}", self);
    }
}

fn send_json_writer<T: Serialize>(writer: &Arc<Mutex<TcpStream>>, msg: &T) -> Result<()> {
    let mut data = serde_json::to_vec(msg)?;
    data.push(0);
    let mut w = writer.lock().unwrap();
    w.write_all(&data)?;
    Ok(())
}

fn send_server_writer(writer: &Arc<Mutex<TcpStream>>, msg: &ServerMessage) -> Result<()> {
    send_json_writer(writer, msg)
}

struct LeftoverReader {
    buf: Vec<u8>,
    pos: usize,
    inner: TcpStream,
    eof: bool,
}

impl Read for LeftoverReader {
    fn read(&mut self, out: &mut [u8]) -> io::Result<usize> {
        if self.pos < self.buf.len() {
            let n = std::cmp::min(out.len(), self.buf.len() - self.pos);
            out[..n].copy_from_slice(&self.buf[self.pos..self.pos + n]);
            self.pos += n;
            if self.pos >= self.buf.len() {
                self.buf.clear();
                self.pos = 0;
            }
            return Ok(n);
        }
        if self.eof {
            return Ok(0);
        }
        self.inner.read(out)
    }
}

struct ProxyEndpoint {
    reader: Box<dyn Read + Send>,
    writer: TcpStream,
    handle: TcpStream,
}

impl ProxyEndpoint {
    fn from_stream(stream: TcpStream) -> Result<Self> {
        let reader_stream = stream.try_clone()?;
        let writer = stream.try_clone()?;
        Ok(ProxyEndpoint {
            reader: Box::new(reader_stream),
            writer,
            handle: stream,
        })
    }
}

fn copy_bidirectional(a: ProxyEndpoint, b: ProxyEndpoint) -> Result<()> {
    let a_handle_1 = a.handle.try_clone()?;
    let a_handle_2 = a.handle.try_clone()?;
    let b_handle_1 = b.handle.try_clone()?;
    let b_handle_2 = b.handle.try_clone()?;

    let ProxyEndpoint {
        reader: a_reader,
        writer: a_writer,
        handle: _a_handle_keep,
    } = a;
    let ProxyEndpoint {
        reader: b_reader,
        writer: b_writer,
        handle: _b_handle_keep,
    } = b;

    let thread = thread::spawn(move || {
        copy_one_direction(a_reader, b_writer, &[a_handle_1, b_handle_1])
    });
    let result_other = copy_one_direction(b_reader, a_writer, &[a_handle_2, b_handle_2]);
    let result_thread = thread
        .join()
        .unwrap_or_else(|_| Err(anyhow!("proxy thread panicked")));

    // Prefer the error from the b->a direction if both failed (matches the
    // most common observation for the client side); otherwise report
    // whichever failed.
    match (result_other, result_thread) {
        (Err(e), _) => Err(e),
        (Ok(()), Err(e)) => Err(e),
        (Ok(()), Ok(())) => Ok(()),
    }
}

fn copy_one_direction(
    mut reader: Box<dyn Read + Send>,
    mut writer: TcpStream,
    shutdown_handles: &[TcpStream],
) -> Result<()> {
    let mut buf = [0u8; 8192];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => {
                let _ = writer.shutdown(Shutdown::Write);
                return Ok(());
            }
            Ok(n) => {
                if let Err(e) = writer.write_all(&buf[..n]) {
                    for h in shutdown_handles {
                        let _ = h.shutdown(Shutdown::Both);
                    }
                    return Err(e.into());
                }
            }
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => {
                for h in shutdown_handles {
                    let _ = h.shutdown(Shutdown::Both);
                }
                return Err(e.into());
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Connecting with optional client-side authentication.

fn client_handshake(auth: &Authenticator, stream: &mut Delimited) -> Result<()> {
    match stream.recv_server_initial()? {
        Some(ServerMessage::Challenge(challenge)) => {
            stream.send_client(&ClientMessage::Authenticate(auth.answer(&challenge)))?;
            Ok(())
        }
        _ => bail!("expected authentication challenge, but no secret was required"),
    }
}

fn connect_delimited(
    to: &str,
    authenticator: Option<&Authenticator>,
    first_message: &ClientMessage,
) -> Result<Delimited> {
    let addr = format!("{}:{}", to, CONTROL_PORT);
    let stream = TcpStream::connect(&addr)
        .with_context(|| format!("could not connect to {}", addr))?;
    let mut delimited = Delimited::new(stream)?;
    if let Some(auth) = authenticator {
        client_handshake(auth, &mut delimited)?;
    }
    delimited.send_client(first_message)?;
    Ok(delimited)
}

// ---------------------------------------------------------------------------
// Client (the `local` subcommand).

#[derive(Clone)]
struct ClientConfig {
    local_host: String,
    local_port: u16,
    to: String,
    remote_port: u16,
    authenticator: Option<Arc<Authenticator>>,
}

fn run_client(cfg: ClientConfig) -> Result<()> {
    let mut stream = connect_delimited(
        &cfg.to,
        cfg.authenticator.as_deref(),
        &ClientMessage::Hello(cfg.remote_port),
    )?;

    let remote_port = match stream.recv_server_initial()? {
        Some(ServerMessage::Hello(port)) => port,
        Some(ServerMessage::Challenge(_)) => {
            bail!("server requires authentication, but no client secret was provided")
        }
        Some(ServerMessage::Error(err)) => bail!("server error: {}", err),
        Some(_) => bail!("unexpected initial non-hello message"),
        None => bail!("unexpected EOF"),
    };

    log_info(
        "bore_cli::client",
        None,
        "connected to server",
        &[("remote_port", remote_port.to_string())],
    );
    log_info(
        "bore_cli::client",
        None,
        &format!("listening at {}:{}", cfg.to, remote_port),
        &[],
    );

    loop {
        let msg = match stream.recv_server()? {
            Some(m) => m,
            None => break,
        };
        match msg {
            ServerMessage::Connection(id) => {
                let cfg2 = cfg.clone();
                thread::spawn(move || {
                    let span = Span::proxy(id);
                    log_info("bore_cli::client", Some(&span), "new connection", &[]);
                    match handle_proxy(id, &cfg2) {
                        Ok(()) => {
                            log_info("bore_cli::client", Some(&span), "connection exited", &[])
                        }
                        Err(err) => log_warn(
                            "bore_cli::client",
                            Some(&span),
                            "connection exited with error",
                            &[("err", err.to_string())],
                        ),
                    }
                });
            }
            ServerMessage::Heartbeat => {}
            ServerMessage::Challenge(_) => {
                log_warn("bore_cli::client", None, "unexpected challenge", &[])
            }
            ServerMessage::Hello(_) => {
                log_warn("bore_cli::client", None, "unexpected hello", &[])
            }
            ServerMessage::Error(err) => {
                log_error(
                    "bore_cli::client",
                    None,
                    "server error",
                    &[("err", err)],
                )
            }
        }
    }
    Ok(())
}

fn handle_proxy(id: Uuid, cfg: &ClientConfig) -> Result<()> {
    let remote = connect_delimited(
        &cfg.to,
        cfg.authenticator.as_deref(),
        &ClientMessage::Accept(id),
    )?;
    let addr = format!("{}:{}", cfg.local_host, cfg.local_port);
    let local_stream = TcpStream::connect(&addr)
        .with_context(|| format!("could not connect to {}", addr))?;
    let local_endpoint = ProxyEndpoint::from_stream(local_stream)?;
    copy_bidirectional(remote.into_endpoint(), local_endpoint)
}

// ---------------------------------------------------------------------------
// Server.

struct ServerState {
    port_range: std::ops::RangeInclusive<u16>,
    connections: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
    authenticator: Option<Arc<Authenticator>>,
    bind_tunnels: IpAddr,
}

fn server_handshake(auth: &Authenticator, stream: &mut Delimited) -> Result<()> {
    let challenge = Uuid::new_v4();
    stream.send_server(&ServerMessage::Challenge(challenge))?;
    match stream.recv_client_initial()? {
        Some(ClientMessage::Authenticate(response)) => {
            if auth.verify(&challenge, &response) {
                Ok(())
            } else {
                bail!("invalid secret")
            }
        }
        _ => bail!("server requires secret, but no secret was provided"),
    }
}

fn random_port_in_range(range: &std::ops::RangeInclusive<u16>) -> u16 {
    let start = *range.start() as u32;
    let end = *range.end() as u32;
    let len = end - start + 1;
    if len <= 1 {
        return *range.start();
    }
    let r = Uuid::new_v4().as_u128() as u32;
    (start + (r % len)) as u16
}

fn create_tunnel_listener(
    state: &ServerState,
    requested: u16,
) -> std::result::Result<TcpListener, String> {
    if requested == 0 {
        for _ in 0..100 {
            let port = random_port_in_range(&state.port_range);
            if let Ok(listener) = TcpListener::bind((state.bind_tunnels, port)) {
                return Ok(listener);
            }
        }
        Err("failed to find an available port".to_string())
    } else if !state.port_range.contains(&requested) {
        Err("client port number not in allowed range".to_string())
    } else {
        match TcpListener::bind((state.bind_tunnels, requested)) {
            Ok(l) => Ok(l),
            Err(e) if e.kind() == io::ErrorKind::AddrInUse => {
                Err("port already in use".to_string())
            }
            Err(_) => Err("failed to bind to port".to_string()),
        }
    }
}

struct TunnelShared {
    shutdown: bool,
    heartbeat_failed: bool,
}

fn handle_listener(
    listener: TcpListener,
    writer: Arc<Mutex<TcpStream>>,
    port: u16,
    span: &Span,
    connections: Arc<Mutex<HashMap<Uuid, TcpStream>>>,
) -> Result<()> {
    listener.set_nonblocking(true).ok();
    let shared = Arc::new((
        Mutex::new(TunnelShared {
            shutdown: false,
            heartbeat_failed: false,
        }),
        Condvar::new(),
    ));

    // Heartbeat thread: first tick is immediate, then every 500ms.
    let hb_writer = Arc::clone(&writer);
    let hb_shared = Arc::clone(&shared);
    let heartbeat_thread = thread::spawn(move || loop {
        {
            let (lock, _) = &*hb_shared;
            let s = lock.lock().unwrap();
            if s.shutdown {
                break;
            }
        }
        if send_server_writer(&hb_writer, &ServerMessage::Heartbeat).is_err() {
            let (lock, cvar) = &*hb_shared;
            let mut s = lock.lock().unwrap();
            s.heartbeat_failed = true;
            s.shutdown = true;
            cvar.notify_all();
            break;
        }
        let (lock, cvar) = &*hb_shared;
        let s = lock.lock().unwrap();
        if s.shutdown {
            break;
        }
        let _ = cvar.wait_timeout(s, HEARTBEAT_INTERVAL);
    });

    let finish = |result: Result<()>| -> Result<()> {
        {
            let (lock, cvar) = &*shared;
            let mut s = lock.lock().unwrap();
            s.shutdown = true;
            cvar.notify_all();
        }
        let _ = heartbeat_thread.join();
        result
    };

    loop {
        {
            let (lock, _) = &*shared;
            let s = lock.lock().unwrap();
            if s.heartbeat_failed {
                return finish(Ok(()));
            }
            if s.shutdown {
                return finish(Ok(()));
            }
        }
        match listener.accept() {
            Ok((stream, addr)) => {
                log_info(
                    "bore_cli::server",
                    Some(span),
                    "new connection",
                    &[
                        ("addr", addr.to_string()),
                        ("port", port.to_string()),
                    ],
                );
                let id = Uuid::new_v4();
                {
                    let mut map = connections.lock().unwrap();
                    map.insert(id, stream);
                }
                if let Err(e) = send_server_writer(&writer, &ServerMessage::Connection(id)) {
                    return finish(Err(e));
                }
            }
            Err(e) if e.kind() == io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(2));
            }
            Err(e) => {
                return finish(Err(e.into()));
            }
        }
    }
}

fn handle_server_connection(
    state: Arc<ServerState>,
    stream: TcpStream,
    span: &Span,
) -> Result<()> {
    log_info("bore_cli::server", Some(span), "incoming connection", &[]);
    let mut delimited = Delimited::new(stream)?;

    if let Some(auth) = &state.authenticator {
        if let Err(err) = server_handshake(auth, &mut delimited) {
            log_warn(
                "bore_cli::server",
                Some(span),
                "server handshake failed",
                &[("err", err.to_string())],
            );
            delimited.send_server(&ServerMessage::Error(err.to_string()))?;
            return Ok(());
        }
    }

    let message = match delimited.recv_client_initial()? {
        Some(m) => m,
        None => return Ok(()),
    };

    match message {
        ClientMessage::Hello(requested_port) => {
            let listener = match create_tunnel_listener(&state, requested_port) {
                Ok(l) => l,
                Err(msg) => {
                    delimited.send_server(&ServerMessage::Error(msg))?;
                    return Ok(());
                }
            };
            let actual_port = listener.local_addr()?.port();
            log_info(
                "bore_cli::server",
                Some(span),
                "new client",
                &[
                    ("host", state.bind_tunnels.to_string()),
                    ("port", actual_port.to_string()),
                ],
            );
            delimited.send_server(&ServerMessage::Hello(actual_port))?;
            let writer = delimited.writer_handle();
            handle_listener(
                listener,
                writer,
                actual_port,
                span,
                Arc::clone(&state.connections),
            )?;
        }
        ClientMessage::Accept(id) => {
            log_info(
                "bore_cli::server",
                Some(span),
                "forwarding connection",
                &[("id", id.to_string())],
            );
            let pending = {
                let mut map = state.connections.lock().unwrap();
                map.remove(&id)
            };
            if let Some(pending_stream) = pending {
                let pending_endpoint = ProxyEndpoint::from_stream(pending_stream)?;
                copy_bidirectional(delimited.into_endpoint(), pending_endpoint)?;
            } else {
                log_warn(
                    "bore_cli::server",
                    Some(span),
                    "missing connection",
                    &[("id", id.to_string())],
                );
            }
        }
        ClientMessage::Authenticate(_) => {
            log_warn("bore_cli::server", Some(span), "unexpected authenticate", &[]);
        }
    }
    Ok(())
}

fn run_server(
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: IpAddr,
    bind_tunnels: Option<IpAddr>,
) -> Result<()> {
    let bind_tunnels = bind_tunnels.unwrap_or(bind_addr);
    let listener = TcpListener::bind((bind_addr, CONTROL_PORT))?;
    log_info(
        "bore_cli::server",
        None,
        "server listening",
        &[("addr", bind_addr.to_string())],
    );
    let state = Arc::new(ServerState {
        port_range: min_port..=max_port,
        connections: Arc::new(Mutex::new(HashMap::new())),
        authenticator: secret
            .as_deref()
            .map(|s| Arc::new(Authenticator::new(s))),
        bind_tunnels,
    });
    loop {
        let (stream, addr) = listener.accept()?;
        let span = Span::control(&addr.to_string());
        let state2 = Arc::clone(&state);
        thread::spawn(move || {
            match handle_server_connection(state2, stream, &span) {
                Ok(()) => log_info("bore_cli::server", Some(&span), "connection exited", &[]),
                Err(err) => log_warn(
                    "bore_cli::server",
                    Some(&span),
                    "connection exited with error",
                    &[("err", err.to_string())],
                ),
            }
        });
    }
}

// ---------------------------------------------------------------------------
// CLI.

fn build_cli() -> Command {
    let local = Command::new("local")
        .about("Starts a local proxy to the remote server")
        .arg(
            Arg::new("local_port")
                .help("The local port to expose")
                .required(true)
                .env("BORE_LOCAL_PORT")
                .value_parser(value_parser!(u16)),
        )
        .arg(
            Arg::new("local_host")
                .short('l')
                .long("local-host")
                .value_name("HOST")
                .help("The local host to expose")
                .default_value("localhost"),
        )
        .arg(
            Arg::new("to")
                .short('t')
                .long("to")
                .help("Address of the remote server to expose local ports to")
                .required(true)
                .env("BORE_SERVER"),
        )
        .arg(
            Arg::new("port")
                .short('p')
                .long("port")
                .help("Optional port on the remote server to select")
                .default_value("0")
                .value_parser(value_parser!(u16)),
        )
        .arg(
            Arg::new("secret")
                .short('s')
                .long("secret")
                .help("Optional secret for authentication")
                .env("BORE_SECRET")
                .hide_env_values(true),
        );

    let server = Command::new("server")
        .about("Runs the remote proxy server")
        .arg(
            Arg::new("min_port")
                .long("min-port")
                .help("Minimum accepted TCP port number")
                .env("BORE_MIN_PORT")
                .default_value("1024")
                .value_parser(value_parser!(u16)),
        )
        .arg(
            Arg::new("max_port")
                .long("max-port")
                .help("Maximum accepted TCP port number")
                .env("BORE_MAX_PORT")
                .default_value("65535")
                .value_parser(value_parser!(u16)),
        )
        .arg(
            Arg::new("secret")
                .short('s')
                .long("secret")
                .help("Optional secret for authentication")
                .env("BORE_SECRET")
                .hide_env_values(true),
        )
        .arg(
            Arg::new("bind_addr")
                .long("bind-addr")
                .help("IP address to bind to, clients must reach this")
                .default_value("0.0.0.0")
                .value_parser(value_parser!(IpAddr)),
        )
        .arg(
            Arg::new("bind_tunnels")
                .long("bind-tunnels")
                .help("IP address where tunnels will listen on, defaults to --bind-addr")
                .value_parser(value_parser!(IpAddr)),
        );

    Command::new("bore-cli")
        .version(env!("CARGO_PKG_VERSION"))
        .about("A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.")
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(local)
        .subcommand(server)
}

fn main() -> Result<()> {
    init_logger();

    // Handle the malformed span-field warning before clap parsing, matching
    // the reference which initialises its logger first. Our parser above
    // prints a slightly different line for that narrow case; correct it by
    // re-checking here is not possible (the line has already been printed),
    // so that special case is handled in parse_env_filter. See note there.

    let matches = build_cli().get_matches();
    match matches.subcommand() {
        Some(("local", sub)) => {
            let local_port = *sub.get_one::<u16>("local_port").unwrap();
            let local_host = sub.get_one::<String>("local_host").unwrap().clone();
            let to = sub.get_one::<String>("to").unwrap().clone();
            let port = *sub.get_one::<u16>("port").unwrap();
            let secret = sub.get_one::<String>("secret").cloned();
            let cfg = ClientConfig {
                local_host,
                local_port,
                to,
                remote_port: port,
                authenticator: secret
                    .as_deref()
                    .map(|s| Arc::new(Authenticator::new(s))),
            };
            run_client(cfg)
        }
        Some(("server", sub)) => {
            let min_port = *sub.get_one::<u16>("min_port").unwrap();
            let max_port = *sub.get_one::<u16>("max_port").unwrap();
            if min_port > max_port {
                build_cli()
                    .error(clap::error::ErrorKind::InvalidValue, "port range is empty")
                    .exit();
            }
            let secret = sub.get_one::<String>("secret").cloned();
            let bind_addr = *sub.get_one::<IpAddr>("bind_addr").unwrap();
            let bind_tunnels = sub.get_one::<IpAddr>("bind_tunnels").copied();
            run_server(min_port, max_port, secret, bind_addr, bind_tunnels)
        }
        _ => unreachable!(),
    }
}
RS
