import pathlib
p=pathlib.Path("Cargo.toml"); s=p.read_text(); s=s.replace('anyhow = "1"\n','anyhow = "1"\nanstream = "1"\n'); p.write_text(s)
p=pathlib.Path("src/main.rs"); s=p.read_text()
helper=r'''
fn strip_ansi(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            // Consume a CSI-style sequence through its final byte.
            let mut next = chars.next();
            if next == Some('[') {
                for c2 in chars.by_ref() {
                    if ('@'..='~').contains(&c2) {
                        break;
                    }
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn fix_clap_rendered(rendered: &str, err: &clap::Error) -> Option<String> {
    let plain = strip_ansi(rendered);
    match err.kind() {
        clap::error::ErrorKind::InvalidSubcommand => {
            if !plain.contains("a similar subcommand exists:") || plain.contains("to pass '") {
                return None;
            }
            let invalid = plain.split('\'').nth(1)?;
            let usage_line = plain.lines().find(|l| l.starts_with("Usage:"))?;
            let bin = usage_line
                .strip_prefix("Usage:")?
                .trim()
                .split_whitespace()
                .next()?;
            let marker = "a similar subcommand exists:";
            let marker_pos = rendered.find(marker)?;
            let line_end = rendered[marker_pos..].find('\n')? + marker_pos + 1;
            let tip = format!(
                "  \x1b[32mtip:\x1b[0m to pass '\x1b[33m{}\x1b[0m' as a value, use '\x1b[32m{} -- {}\x1b[0m'\n",
                invalid, bin, invalid
            );
            let mut out = String::with_capacity(rendered.len() + tip.len());
            out.push_str(&rendered[..line_end]);
            out.push_str(&tip);
            out.push_str(&rendered[line_end..]);
            Some(out)
        }
        clap::error::ErrorKind::UnknownArgument => {
            let usage_line = plain.lines().find(|l| l.starts_with("Usage:"))?;
            let mut parts = usage_line.strip_prefix("Usage:")?.trim().splitn(2, ' ');
            let _bin = parts.next()?;
            let rest = parts.next().unwrap_or("");
            let (subcommand, remainder) = rest.split_once(' ').unwrap_or((rest, ""));
            let alternation = match subcommand {
                "local" if remainder != "[OPTIONS] --to <TO> <LOCAL_PORT>" => {
                    "<LOCAL_PORT|--local-host <HOST>|--to <TO>|--port <PORT>|--secret <SECRET>>"
                }
                "server" if remainder != "[OPTIONS]" => {
                    "<--min-port <MIN_PORT>|--max-port <MAX_PORT>|--secret <SECRET>|--bind-addr <BIND_ADDR>|--bind-tunnels <BIND_TUNNELS>>"
                }
                _ => return None,
            };
            let usage_marker = "Usage:\x1b[0m ";
            let usage_start = rendered.find(usage_marker)? + usage_marker.len();
            // The bin name and subcommand are a single bold segment ending
            // at the next reset code, followed by a space.
            let bold_end_rel = rendered[usage_start..].find("\x1b[0m")?;
            let after_bold = usage_start + bold_end_rel + "\x1b[0m".len();
            if rendered[after_bold..].chars().next() != Some(' ') {
                return None;
            }
            let line_end = rendered[after_bold..].find('\n')? + after_bold;
            let mut out = String::with_capacity(rendered.len() + alternation.len());
            out.push_str(&rendered[..after_bold + 1]);
            out.push_str(alternation);
            out.push_str(&rendered[line_end..]);
            Some(out)
        }
        _ => None,
    }
}

fn get_cli_matches() -> clap::ArgMatches {
    match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(err) => {
            if let Some(fixed) = fix_clap_rendered(&err.render().ansi().to_string(), &err) {
                if err.use_stderr() {
                    anstream::eprint!("{}", fixed);
                } else {
                    anstream::print!("{}", fixed);
                }
                std::process::exit(err.exit_code());
            } else {
                err.exit()
            }
        }
    }
}

