#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct BoreUuid([u8; 16]);

impl BoreUuid {
    fn new_v4() -> Self {
        BoreUuid(*Uuid::new_v4().as_bytes())
    }

    fn as_bytes(&self) -> &[u8; 16] {
        &self.0
    }

    fn parse_legacy(input: &str) -> std::result::Result<Self, String> {
        let (segment, offset, forced_hyphenated) = if let Some(rest) = input.strip_prefix("urn:uuid:") {
            (rest, 9usize, true)
        } else if input.len() >= 2 && input.starts_with('{') && input.ends_with('}') {
            (&input[1..input.len() - 1], 1usize, true)
        } else {
            (input, 0usize, false)
        };

        for (byte_idx, c) in segment.char_indices() {
            if !(c.is_ascii_hexdigit() || c == '-') {
                return Err(format!(
                    "invalid character: expected an optional prefix of `urn:uuid:` followed by [0-9a-fA-F-], found `{}` at {}",
                    c,
                    offset + byte_idx + 1
                ));
            }
        }

        let hex_chars: Vec<u8>;
        if forced_hyphenated || segment.contains('-') {
            let groups: Vec<&str> = segment.split('-').collect();
            if groups.len() != 5 {
                return Err(format!(
                    "invalid group count: expected 5, found {}",
                    groups.len()
                ));
            }
            let expected = [8usize, 4, 4, 4, 12];
            for (i, group) in groups.iter().enumerate() {
                if group.len() != expected[i] {
                    // The reference UUID parser reports the final group's
                    // length relative to the whole input string (so any
                    // `urn:uuid:` prefix or braces are included).
                    let found = if i == 4 {
                        input.len() - 24
                    } else {
                        group.len()
                    };
                    return Err(format!(
                        "invalid group length in group {}: expected {}, found {}",
                        i, expected[i], found
                    ));
                }
            }
            hex_chars = groups.concat().into_bytes();
        } else {
            if segment.len() != 32 {
                return Err(format!(
                    "invalid length: expected length 32 for simple format, found {}",
                    segment.len()
                ));
            }
            hex_chars = segment.as_bytes().to_vec();
        }

        let mut bytes = [0u8; 16];
        for i in 0..16 {
            let hi = (hex_chars[2 * i] as char).to_digit(16).unwrap() as u8;
            let lo = (hex_chars[2 * i + 1] as char).to_digit(16).unwrap() as u8;
            bytes[i] = (hi << 4) | lo;
        }
        Ok(BoreUuid(bytes))
    }
}

impl std::fmt::Display for BoreUuid {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let b = &self.0;
        write!(
            f,
            "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8], b[9], b[10], b[11], b[12],
            b[13], b[14], b[15]
        )
    }
}

impl Serialize for BoreUuid {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        serializer.serialize_str(&self.to_string())
    }
}

impl<'de> Deserialize<'de> for BoreUuid {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> std::result::Result<Self, D::Error> {
        struct UuidVisitor;
        impl serde::de::Visitor<'_> for UuidVisitor {
            type Value = BoreUuid;

            fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                formatter.write_str("a UUID string")
            }

