new='''fn copy_bidirectional(a: ProxyEndpoint, b: ProxyEndpoint) -> Result<()> {
    let abort = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let abort_thread = Arc::clone(&abort);
    let a_stream_thread = Arc::clone(&a.stream);
    let b_stream_thread = Arc::clone(&b.stream);
    let thread = thread::spawn(move || {
        copy_one_direction(a.reader, b_stream_thread, a_stream_thread, abort_thread)
    });
    let result_other = copy_one_direction(b.reader, a.stream, b.stream, abort);
    let result_thread = thread
        .join()
        .unwrap_or_else(|_| Err(anyhow!("proxy thread panicked")));

    match (result_other, result_thread) {
        (Err(e), _) => Err(e),
        (Ok(()), Err(e)) => Err(e),
        (Ok(()), Ok(())) => Ok(()),
    }
}

fn copy_one_direction(
    mut reader: Box<dyn Read + Send>,
    dest: Arc<TcpStream>,
    source: Arc<TcpStream>,
    abort: Arc<std::sync::atomic::AtomicBool>,
) -> Result<()> {
    use std::sync::atomic::Ordering;
    let fail = |e: io::Error,
                  abort: &std::sync::atomic::AtomicBool,
                  source: &TcpStream,
                  dest: &TcpStream|
     -> Result<()> {
        if abort.swap(true, Ordering::AcqRel) {
            // Another direction already failed and shut the sockets down;
            // treat errors induced by that shutdown as a clean exit so the
            // original error is the one reported.
            Ok(())
        } else {
            let _ = source.shutdown(Shutdown::Both);
            let _ = dest.shutdown(Shutdown::Both);
            Err(e.into())
        }
    };
    let mut buf = [0u8; 8192];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => match dest.shutdown(Shutdown::Write) {
                Ok(()) => return Ok(()),
                Err(e) => return fail(e, &abort, &source, &dest),
            },
            Ok(n) => {
                let mut writer: &TcpStream = &dest;
                if let Err(e) = writer.write_all(&buf[..n]) {
                    return fail(e, &abort, &source, &dest);
                }
            }
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return fail(e, &abort, &source, &dest),
        }
    }
}
