fn line_col_to_byte(frame: &[u8], target_line: usize, target_col: usize) -> Option<usize> {
    let mut line = 1usize;
    let mut col = 1usize;
    for (i, &b) in frame.iter().enumerate() {
        if line == target_line && col == target_col {
            return Some(i);
        }
        if b == b'\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    if line == target_line && col == target_col {
        Some(frame.len())
    } else {
        None
    }
}

fn legacy_json_error_string(frame: &[u8], err: &serde_json::Error) -> Option<String> {
    let original = err.to_string();

    // Current serde_json reports a non-string first object key in an
    // externally-tagged enum as "key must be a string". The version used by
    // the reference attempted to parse that key as a value (the variant
    // identifier), producing the older messages recreated here.
    if original.starts_with("key must be a string") {
        let mut idx = 0usize;
        let mut line = 1usize;
        let mut col = 1usize;
        let mut advance_ws = |idx: &mut usize, line: &mut usize, col: &mut usize| {
            while *idx < frame.len() && matches!(frame[*idx], b' ' | b'\t' | b'\r' | b'\n') {
                if frame[*idx] == b'\n' {
                    *line += 1;
                    *col = 1;
                } else {
                    *col += 1;
                }
                *idx += 1;
            }
        };
        advance_ws(&mut idx, &mut line, &mut col);
        if idx >= frame.len() || frame[idx] != b'{' {
            return None;
        }
        let brace_line = line;
        let brace_col = col;
        idx += 1;
        col += 1;
        advance_ws(&mut idx, &mut line, &mut col);
        if idx >= frame.len() {
            return None;
        }
        let key_line = line;
        let key_col = col;
        let key_idx = idx;
        let msg = match frame[idx] {
            b'[' => format!(
                "invalid type: sequence, expected variant identifier at line {} column {}",
                brace_line, brace_col
            ),
            b'{' => format!(
                "invalid type: map, expected variant identifier at line {} column {}",
                brace_line, brace_col
            ),
            b't' if frame[idx..].starts_with(b"true")
                && frame
                    .get(idx + 4)
                    .map(|b| matches!(b, b' ' | b'\t' | b'\r' | b'\n' | b':' | b',' | b'}'))
                    .unwrap_or(true) =>
            {
                format!(
                    "invalid type: boolean `true`, expected variant identifier at line {} column {}",
                    key_line,
                    key_col + 3
                )
            }
            b'f' if frame[idx..].starts_with(b"false")
                && frame
                    .get(idx + 5)
                    .map(|b| matches!(b, b' ' | b'\t' | b'\r' | b'\n' | b':' | b',' | b'}'))
                    .unwrap_or(true) =>
            {
                format!(
                    "invalid type: boolean `false`, expected variant identifier at line {} column {}",
                    key_line,
                    key_col + 4
                )
            }
            b'n' if frame[idx..].starts_with(b"null")
                && frame
                    .get(idx + 4)
                    .map(|b| matches!(b, b' ' | b'\t' | b'\r' | b'\n' | b':' | b',' | b'}'))
                    .unwrap_or(true) =>
            {
                format!(
                    "invalid type: null, expected variant identifier at line {} column {}",
                    key_line,
                    key_col + 3
                )
            }
            b'-' | b'0'..=b'9' => {
                // Scan a JSON number.
                let mut i = idx;
                if frame[i] == b'-' {
                    i += 1;
                }
                let mut valid = i < frame.len() && frame[i].is_ascii_digit();
                let mut is_float = false;
                if valid {
                    if frame[i] == b'0' {
                        i += 1;
                    } else {
                        while i < frame.len() && frame[i].is_ascii_digit() {
                            i += 1;
                        }
                    }
                    if i < frame.len() && frame[i] == b'.' {
                        is_float = true;
                        i += 1;
                        if i >= frame.len() || !frame[i].is_ascii_digit() {
                            valid = false;
                        }
                        while i < frame.len() && frame[i].is_ascii_digit() {
                            i += 1;
                        }
                    }
                    if valid && i < frame.len() && matches!(frame[i], b'e' | b'E') {
                        is_float = true;
                        i += 1;
                        if i < frame.len() && matches!(frame[i], b'+' | b'-') {
                            i += 1;
                        }
                        if i >= frame.len() || !frame[i].is_ascii_digit() {
                            valid = false;
                        }
                        while i < frame.len() && frame[i].is_ascii_digit() {
                            i += 1;
                        }
                    }
                }
                let followed_ok = frame
                    .get(i)
                    .map(|b| matches!(b, b' ' | b'\t' | b'\r' | b'\n' | b':' | b',' | b'}'))
                    .unwrap_or(true);
                if valid && followed_ok && i - key_idx <= 19 {
                    let token = std::str::from_utf8(&frame[key_idx..i]).ok()?;
                    if is_float {
                        let value: f64 = token.parse().ok()?;
                        format!(
                            "invalid type: floating point `{}`, expected variant identifier at line {} column {}",
                            value,
                            key_line,
                            key_col + token.len() - 1
                        )
                    } else {
                        format!(
                            "invalid type: integer `{}`, expected variant identifier at line {} column {}",
                            token,
                            key_line,
                            key_col + token.len() - 1
                        )
                    }
                } else {
                    format!(
                        "expected value at line {} column {}",
                        key_line, key_col
                    )
                }
            }
            _ => format!(
                "expected value at line {} column {}",
                key_line, key_col
            ),
        };
        return Some(msg);
    }

    // Opening an object and then hitting EOF before any key.
    if original.starts_with("EOF while parsing an object") {
        let mut i = 0usize;
        while i < frame.len() && matches!(frame[i], b' ' | b'\t' | b'\r' | b'\n') {
            i += 1;
        }
        if i < frame.len()
            && frame[i] == b'{'
            && frame[i + 1..]
                .iter()
                .all(|b| matches!(b, b' ' | b'\t' | b'\r' | b'\n'))
        {
            return Some(original.replacen(
                "EOF while parsing an object",
                "EOF while parsing a value",
                1,
            ));
        }
    }

    // Invalid \uXXXX escapes: older serde_json pointed at the first
    // non-hex digit, current versions point after the four digits.
    if original.starts_with("invalid escape") {
        if let Some((_, line, col)) = split_error_line_col(&original) {
            if let Some(offset) = line_col_to_byte(frame, line, col) {
                let mut start = 0usize;
                while start + 1 < frame.len() {
                    if frame[start] == b'\\' && frame[start + 1] == b'u' {
                        let first_bad = (0..4).find_map(|j| {
                            let pos = start + 2 + j;
                            match frame.get(pos) {
                                Some(b) if b.is_ascii_hexdigit() => None,
                                _ => Some(pos),
                            }
                        });
                        if let Some(pos) = first_bad {
                            if start + 2 <= offset && offset <= start + 5 && pos <= offset {
                                let (l, c) = byte_line_col(frame, pos);
                                return Some(format!(
                                    "invalid escape at line {} column {}",
                                    l, c
                                ));
                            }
                        }
                    }
                    start += 1;
                }
            }
        }
        return None;
    }

    // Floating-point values in "invalid type" errors were formatted with
    // Display (e.g. `1000`) rather than Debug (e.g. `1000.0`).
    if let Some(float_pos) = original.find("floating point `") {
        let token_start = float_pos + "floating point `".len();
        if let Some(rel_end) = original[token_start..].find('`') {
            let token = &original[token_start..token_start + rel_end];
            if let Ok(value) = token.parse::<f64>() {
                let formatted = value.to_string();
                if formatted != token {
                    let mut out = original.clone();
                    out.replace_range(token_start..token_start + rel_end, &formatted);
                    return Some(out);
                }
            }
        }
    }

    None
}

